    /** La época cuyas texturas se usan (las que aún no están dibujadas, la medieval). */
    public static Epoca dibujo(Epoca e) {
        return DIBUJADA[e.ordinal()] ? e : Epoca.MEDIEVAL;
    }

    /** Un peinado al azar de su época (los de solo adultos, menos a menudo). */
    public static int peinadoAlAzar(Epoca e, boolean mujer, RandomSource azar) {
        boolean[] adulto = SOLO_ADULTO[dibujo(e).ordinal()][mujer ? 1 : 0];
        int n = azar.nextInt(adulto.length);
        return adulto[n] && azar.nextBoolean() ? azar.nextInt(adulto.length) : n;
    }
